/**
 * Image Gallery with Delete Confirmation Dialog
 * Handles rendering the component and managing dialog state
 */

class ImageGalleryApp {
  constructor() {
    this.root = document.getElementById('root');
    this.template = document.getElementById('app-template');
    this.dialog = null;
    this.triggerButton = null;
    this.previousActiveElement = null;
    this.init();
  }

  init() {
    this.render();
    this.setupDialogHandlers();
  }

  render() {
    const clone = this.template.content.cloneNode(true);
    this.root.appendChild(clone);

    this.dialog = document.getElementById('deleteDialog');
    this.triggerButton = document.querySelector('.trigger');
  }

  setupDialogHandlers() {
    const cancelBtn = document.getElementById('cancelBtn');
    const confirmDeleteBtn = document.getElementById('confirmDeleteBtn');
    const closeBtn = document.querySelector('.btn-close');

    this.triggerButton.addEventListener('click', () => this.openDialog());
    cancelBtn.addEventListener('click', () => this.closeDialog());
    closeBtn.addEventListener('click', () => this.closeDialog());
    confirmDeleteBtn.addEventListener('click', () => this.handleDelete());

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.dialog.open) {
        this.closeDialog();
      }
    });
  }

  openDialog() {
    this.previousActiveElement = document.activeElement;
    this.dialog.showModal();

    const confirmBtn = document.getElementById('confirmDeleteBtn');
    confirmBtn.focus();
  }

  closeDialog() {
    this.dialog.close();

    if (this.previousActiveElement) {
      this.previousActiveElement.focus();
    }
  }

  handleDelete() {
    alert('Image deleted successfully!');
    this.closeDialog();
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new ImageGalleryApp();
});

